package org.opentaint.dataflow.bidi

import org.opentaint.dataflow.ap.ifds.AccessPathBase
import org.opentaint.dataflow.bidi.ap.DemandPattern
import org.opentaint.dataflow.bidi.ap.Direction
import org.opentaint.dataflow.bidi.fixtures.MethodAnalysisFixtures
import org.opentaint.dataflow.bidi.interp.MicroEdgeBuilder
import org.opentaint.dataflow.bidi.store.DemandStore
import kotlin.test.*

/** Diagnostic only: compare changed and unchanged arrivals at one relevant operation. */
class RelevantInputDedupInvestigationTest {
    @Test fun `neutral padding permits duplicate relevant evaluation while outputs remain unique`() {
        for (padding in listOf(false, true)) {
            val next = listOf(
                listOf(1, 2),
                listOf(if (padding) 3 else 5),
                listOf(if (padding) 4 else 5),
                listOf(5), listOf(5), listOf(6), emptyList(),
            )
            MethodAnalysisFixtures(next, normalExit = 6).use { f ->
                val p = AccessPathBase.Argument(0)
                val y = AccessPathBase.LocalVar(0)
                val copy = MicroEdgeBuilder().apply { move(y, p) }.build()
                f.statement(1, copy)
                f.statement(2, copy)
                f.statement(5, MicroEdgeBuilder().apply { move(AccessPathBase.Return, y) }.build())
                val demand = DemandStore.Builder(f.manager).apply {
                    add(f.key, DemandPattern(f.pattern(p), f.pattern(AccessPathBase.Return)))
                }.build()
                val actor = f.core(index = 5, L = 4, demand = demand)
                val initial = f.manager.initial(f.pattern(p))
                val admitted = demand.initials(f.key, f.fact(p), demand.admissionPolicy(5, 4, Direction.FORWARD))
                assertEquals(setOf(initial), admitted, "The concrete initial must be obtainable from actual input and demand")
                admitted.forEach(actor::addInitial)
                f.drain(actor, quantum = 1)

                val relevant = f.processed.filter { it.node.location.index == 5 && it.facts.base == y }
                val returned = f.processed.filter { it.node.location.index == 6 && it.facts.base == AccessPathBase.Return }
                val inputRows = actor.edges.edgesAt(f.inst(5), initial).count { it.second.base == y }
                val outputRows = actor.edges.edgesAt(f.inst(6), initial).count { it.second.base == AccessPathBase.Return }
                assertEquals(if (padding) 2 else 1, relevant.size)
                assertEquals(1, returned.size)
                assertEquals(if (padding) 0 else 1, inputRows)
                assertEquals(1, outputRows)
                if (padding) assertEquals(relevant[0], relevant[1], "The complete relevant input is equal")
                val steps = actor.steps
                assertTrue(actor.work(1))
                assertEquals(steps, actor.steps, "The duplicate output does not reopen the fixed point")
                println("RELEVANT_INPUT_DEDUP padding=$padding relevantVisits=${relevant.size} returnedVisits=${returned.size} inputStoreRows=$inputRows outputStoreRows=$outputRows trace=" +
                    f.processed.joinToString { "${it.node.location.index}:${it.facts.base}" })
            }
        }
    }
}
